# Load packages
library(data.table)
library(dplyr)
library(readr)
library(stringr)
library(tidyr)

# Define inputs
# SNP-level association results generated by 01_process_aragwas.R
snp_file <- file.path("results", "aragwas_combined_results.csv")

# AraPheno phenotype metadata included in this repository. The metadata file must contain: phenotype_id, name, to_name.
phenotype_file <- file.path("data", "external", "arapheno", "list_all_phenotypes.csv")

# Define outputs
output_dir <- "results"
dir.create(
  output_dir,
  recursive = TRUE,
  showWarnings = FALSE
)

# Main output containing one effect-size estimate per gene and ontology trait
out_gene_trait_effects <- file.path(output_dir, "gene_trait_effects.csv")

# Main output containing one row per gene and a readable list of its traits and corresponding standardized effect-size estimates
out_gene_trait_table <- file.path(output_dir, "gene_trait_table.csv")

# Main output containing one row per gene and ontology trait, with effect magnitude renamed "abundance" for downstream Hill-diversity calculations
out_gene_trait_collapsed <- file.path(output_dir, "gene_trait_collapsed.csv")

# OPTIONAL: Intermediate gene-by-phenotype summary
out_gene_summary <- file.path(output_dir, "gene_summary_std_with_phenotype.csv")

# CONFIRM: Both input files exist before continuing
stopifnot(
  file.exists(snp_file),
  file.exists(phenotype_file)
)

# Load SNP-level association results
snp_results <- fread(
  snp_file
)

# Apply the AraGWAS significance threshold
# AraGWAS scores are reported as -log10(p). Therefore, score > 4 corresponds to p < 1 x 10^-4
snp_results_filt <- snp_results %>%
  filter(
    score > 4
  )

# Standardize SNP effect sizes within each phenotype
# Divide each beta value by the standard deviation of beta values for its phenotype. This places effect sizes from different phenotypes on a more comparable scale.
snp_results_filt <- snp_results_filt %>%
  group_by(
    phenotype_file
  ) %>%
  mutate(
    beta_std = beta / sd(
      beta,
      na.rm = TRUE
    )
  ) %>%
  ungroup()

# Aggregate SNP effects by gene and phenotype
gene_summary_std <- snp_results_filt %>%
  
  # Separate SNPs mapped to multiple genes into one row per gene
  separate_rows(
    gene,
    sep = ";"
  ) %>%
  
  # Summarize significant SNP effects for each gene within each phenotype.
  group_by(
    phenotype_file,
    gene
  ) %>%
  summarise(
    mean_beta_gene = mean(
      beta_std,
      na.rm = TRUE
    ),
    median_beta_gene = median(
      beta_std,
      na.rm = TRUE
    ),
    mean_abs_beta_gene = mean(
      abs(beta_std),
      na.rm = TRUE
    ),
    max_abs_beta_gene = max(
      abs(beta_std),
      na.rm = TRUE
    ),
    mean_score_gene = mean(
      score,
      na.rm = TRUE
    ),
    max_score_gene = max(
      score,
      na.rm = TRUE
    ),
    num_snps_gene = n(),
    .groups = "drop"
  )

# Load AraPheno metadata
phenotype_list <- read_csv(
  phenotype_file,
  show_col_types = FALSE
) %>%
  select(
    phenotype_id,
    name,
    to_name
  )

# Attach phenotype metadata
gene_summary_std_pheno <- gene_summary_std %>%
  
  # Extract the numeric AraPheno phenotype identifier from each HDF5 filename by removing the .hdf5 extension.
  mutate(
    phenotype_id = as.numeric(
      str_remove(
        phenotype_file,
        "\\.hdf5$"
      )
    )
  ) %>%
  
  # Add the AraPheno phenotype name and ontology trait name
  left_join(
    phenotype_list,
    by = "phenotype_id"
  ) %>%
  
  # Place phenotype metadata before the gene-level summary statistics.
  select(
    phenotype_file,
    phenotype_id,
    name,
    to_name,
    everything()
  )

# OPTIONAL: Intermediate output
# This gene-by-phenotype table is not required by later analysis scripts. Uncomment the following code to save it for inspection or record keeping.

# fwrite(
#  gene_summary_std_pheno,
#  out_gene_summary
#  )

# Remove climate-related phenotypes
# AraGWAS climate phenotype names begin with "clim".
# Rows without phenotype names are removed because they cannot be
# classified as climate or non-climate traits.
gene_summary_no_clim <- gene_summary_std_pheno %>%
  filter(
    !is.na(name),
    !str_detect(
      name,
      "^clim"
    )
  )

# Collapse repeated measurements sharing an ontology trait
# Multiple AraPheno phenotypes may map to the same ontology trait.
# Collapse these measurements so that each gene has one row per
# ontology trait.
gene_trait_effects <- gene_summary_no_clim %>%
  filter(
    !is.na(to_name),
    to_name != ""
  ) %>%
  group_by(
    gene,
    to_name
  ) %>%
  summarise(
    mean_abs_beta_effect = mean(
      mean_abs_beta_gene,
      na.rm = TRUE
    ),
    .groups = "drop"
  ) %>%
  rename(
    trait = to_name
  ) %>%
  arrange(
    gene,
    desc(mean_abs_beta_effect)
  )

# Save gene-by-trait effect estimates
write.csv(
  gene_trait_effects,
  out_gene_trait_effects,
  row.names = FALSE
)

# Create a readable per-gene trait table
# Effect sizes are rounded only for this summary table.
gene_trait_table <- gene_trait_effects %>%
  group_by(
    gene
  ) %>%
  summarise(
    traits = paste(
      paste0(
        trait,
        " (",
        round(
          mean_abs_beta_effect,
          2
        ),
        ")"
      ),
      collapse = "; "
    ),
    .groups = "drop"
  )

# Save the readable per-gene trait table
write.csv(
  gene_trait_table,
  out_gene_trait_table,
  row.names = FALSE
)

# Reformat table for Hill-diversity calculations
# Gene-trait pairs are already unique because they were collapsed above
# Rename the effect-size column to "abundance" for downstream analyses
gene_trait_collapsed <- gene_trait_effects %>%
  transmute(
    gene,
    trait,
    abundance = mean_abs_beta_effect
  )

# Save the collapsed gene-trait table
write.csv(
  gene_trait_collapsed,
  out_gene_trait_collapsed,
  row.names = FALSE
)
